-- ============================================
-- 创建表结构
-- ============================================

-- 表: AI_INSIGHTS
CREATE TABLE AI_INSIGHTS (
    ID NUMBER NOT NULL,
    MACHINE_ID VARCHAR2(4000),
    LOT_ID VARCHAR2(4000),
    INSIGHT_TYPE VARCHAR2(4000),
    CONFIDENCE FLOAT,
    SUMMARY VARCHAR2(4000),
    DETAILS VARCHAR2(4000),
    CREATED_AT VARCHAR2(4000),
    CONSTRAINT PK_AI_INSIGHTS PRIMARY KEY (ID)
);

-- 表: ALARMS
CREATE TABLE ALARMS (
    ID NUMBER NOT NULL,
    MACHINE_ID VARCHAR2(4000),
    "TIMESTAMP" VARCHAR2(4000),
    ALARM_CODE VARCHAR2(4000),
    DESCRIPTION VARCHAR2(4000),
    "LEVEL" VARCHAR2(4000),
    RESOLVED NUMBER(1),
    LOT_ID VARCHAR2(4000),
    CONSTRAINT PK_ALARMS PRIMARY KEY (ID)
);

-- 表: CHAMBER_SNAPSHOTS
CREATE TABLE CHAMBER_SNAPSHOTS (
    ID NUMBER NOT NULL,
    MACHINE_ID VARCHAR2(4000),
    CHAMBER_ID VARCHAR2(4000),
    "TIMESTAMP" VARCHAR2(4000),
    TEMPERATURE FLOAT,
    PRESSURE FLOAT,
    RF_POWER FLOAT,
    GAS_FLOW FLOAT,
    IS_RUNNING NUMBER(1),
    CONSTRAINT PK_CHAMBER_SNAPSHOTS PRIMARY KEY (ID)
);

-- 表: DASHBOARD_KPI
CREATE TABLE DASHBOARD_KPI (
    ID NUMBER NOT NULL,
    MACHINE_ID VARCHAR2(4000),
    "DATE" VARCHAR2(4000),
    CATEGORY VARCHAR2(4000),
    VALUE FLOAT,
    UPDATED_AT VARCHAR2(4000),
    CONSTRAINT PK_DASHBOARD_KPI PRIMARY KEY (ID)
);

-- 表: EVENT_ACTION_MAPPINGS
CREATE TABLE EVENT_ACTION_MAPPINGS (
    ID NUMBER NOT NULL,
    MODEL_ID VARCHAR2(4000) NOT NULL,
    MAPPING_ID VARCHAR2(4000) NOT NULL,
    DESCRIPTION VARCHAR2(4000),
    TRIGGER_EVENT_TYPE VARCHAR2(4000),
    TRIGGER_EVENT_CODE VARCHAR2(4000),
    TRIGGER_CONDITION_JSON VARCHAR2(4000),
    ACTION_SEQUENCE_JSON VARCHAR2(4000),
    ROLLBACK_EVENT_TYPE VARCHAR2(4000),
    ROLLBACK_EVENT_CODE VARCHAR2(4000),
    CREATED_AT VARCHAR2(4000),
    UPDATED_AT VARCHAR2(4000),
    CONSTRAINT PK_EVENT_ACTION_MAPPINGS PRIMARY KEY (ID)
);

-- 表: FLOORS
CREATE TABLE FLOORS (
    ID NUMBER NOT NULL,
    NAME VARCHAR2(4000),
    DESCRIPTION VARCHAR2(4000),
    WIDTH FLOAT,
    HEIGHT FLOAT,
    SVG_MAP VARCHAR2(4000),
    CREATED_AT VARCHAR2(4000),
    UPDATED_AT VARCHAR2(4000),
    CONSTRAINT PK_FLOORS PRIMARY KEY (ID)
);

-- 表: FLOOR_AREAS
CREATE TABLE FLOOR_AREAS (
    ID NUMBER NOT NULL,
    FLOOR_ID NUMBER,
    NAME VARCHAR2(4000),
    AREA_TYPE VARCHAR2(4000),
    X_POS FLOAT,
    Y_POS FLOAT,
    WIDTH FLOAT,
    HEIGHT FLOAT,
    COLOR VARCHAR2(4000),
    DESCRIPTION VARCHAR2(4000),
    CONSTRAINT PK_FLOOR_AREAS PRIMARY KEY (ID)
);

-- 表: LOTS
CREATE TABLE LOTS (
    ID VARCHAR2(4000) NOT NULL,
    MACHINE_ID VARCHAR2(4000),
    PRODUCT VARCHAR2(4000),
    WAFER_COUNT NUMBER,
    STATUS VARCHAR2(4000),
    START_TIME VARCHAR2(4000),
    END_TIME VARCHAR2(4000),
    RECIPE_ID VARCHAR2(4000),
    CONSTRAINT PK_LOTS PRIMARY KEY (ID)
);

-- 表: MACHINES
CREATE TABLE MACHINES (
    ID VARCHAR2(4000) NOT NULL,
    MODEL VARCHAR2(4000),
    NAME VARCHAR2(4000),
    LINE NUMBER,
    FLOOR NUMBER,
    CHAMBER_COUNT NUMBER,
    PROCESS_TYPE VARCHAR2(4000),
    STATE VARCHAR2(4000),
    TEMP FLOAT,
    PRESSURE FLOAT,
    GAS_FLOW FLOAT,
    RF_POWER FLOAT,
    WAFER_COUNT NUMBER,
    ALARM_COUNT NUMBER,
    PROCESS_STEP NUMBER,
    HAS_SMIF NUMBER(1),
    UPDATED_AT VARCHAR2(4000),
    X_POS FLOAT,
    Y_POS FLOAT,
    FLOOR_X FLOAT,
    FLOOR_Y FLOAT,
    CONSTRAINT PK_MACHINES PRIMARY KEY (ID)
);

-- 表: MACHINE_EVENTS
CREATE TABLE MACHINE_EVENTS (
    ID NUMBER NOT NULL,
    MACHINE_ID VARCHAR2(4000),
    "TIMESTAMP" VARCHAR2(4000),
    EVENT_TYPE VARCHAR2(4000),
    EVENT_CODE VARCHAR2(4000),
    DESCRIPTION VARCHAR2(4000),
    "LEVEL" VARCHAR2(4000),
    METRIC VARCHAR2(4000),
    VALUE FLOAT,
    LOT_ID VARCHAR2(4000),
    CONSTRAINT PK_MACHINE_EVENTS PRIMARY KEY (ID)
);

-- 表: MACHINE_MODEL_CONFIGS
CREATE TABLE MACHINE_MODEL_CONFIGS (
    MODEL_ID VARCHAR2(4000) NOT NULL,
    MODEL_NAME VARCHAR2(4000) NOT NULL,
    VENDOR VARCHAR2(4000),
    PROCESS_TYPE VARCHAR2(4000),
    VERSION VARCHAR2(4000),
    VIEW_MODE VARCHAR2(4000),
    DESCRIPTION VARCHAR2(4000),
    VIEWS_CONFIG_JSON CLOB,
    PARTS_CONFIG_JSON CLOB,
    STATE_MAPPING_JSON CLOB,
    HOTSPOTS_CONFIG_JSON CLOB,
    CREATED_AT VARCHAR2(4000),
    UPDATED_AT VARCHAR2(4000),
    CONSTRAINT PK_MACHINE_MODEL_CONFIGS PRIMARY KEY (MODEL_ID)
);

-- 表: MACHINE_TOOL_MAPPINGS
CREATE TABLE MACHINE_TOOL_MAPPINGS (
    ID NUMBER NOT NULL,
    MACHINE_ID VARCHAR2(4000) NOT NULL,
    TOOL_ID VARCHAR2(4000) NOT NULL,
    DESCRIPTION VARCHAR2(4000),
    IS_PRIMARY NUMBER(1),
    CONSTRAINT PK_MACHINE_TOOL_MAPPINGS PRIMARY KEY (ID)
);

-- 表: OHT_POSITIONS
CREATE TABLE OHT_POSITIONS (
    ID NUMBER NOT NULL,
    OHT_ID VARCHAR2(4000),
    LOT_ID VARCHAR2(4000),
    X_POS FLOAT,
    Y_POS FLOAT,
    Z_POS FLOAT,
    STATUS VARCHAR2(4000),
    TARGET_MACHINE_ID VARCHAR2(4000),
    "TIMESTAMP" VARCHAR2(4000),
    CONSTRAINT PK_OHT_POSITIONS PRIMARY KEY (ID)
);

-- 表: PERM_DATA
CREATE TABLE PERM_DATA (
    ID VARCHAR2(4000) NOT NULL,
    PERM_NAME VARCHAR2(4000) NOT NULL,
    PERM_DESC VARCHAR2(4000),
    RES_COL VARCHAR2(4000),
    ACT_COL VARCHAR2(4000),
    CONSTRAINT PK_PERM_DATA PRIMARY KEY (ID)
);

-- 表: RECIPES
CREATE TABLE RECIPES (
    ID VARCHAR2(4000) NOT NULL,
    NAME VARCHAR2(4000),
    MACHINE_ID VARCHAR2(4000),
    PROCESS_TYPE VARCHAR2(4000),
    TEMPERATURE FLOAT,
    PRESSURE FLOAT,
    RF_POWER FLOAT,
    GAS_FLOW FLOAT,
    PROCESS_TIME FLOAT,
    UPDATED_AT VARCHAR2(4000),
    CONSTRAINT PK_RECIPES PRIMARY KEY (ID)
);

-- 表: ROLES
CREATE TABLE ROLES (
    ID VARCHAR2(4000) NOT NULL,
    NAME VARCHAR2(4000) NOT NULL,
    DESCRIPTION VARCHAR2(4000),
    CONSTRAINT PK_ROLES PRIMARY KEY (ID)
);

-- 表: ROLE_PERMISSIONS
CREATE TABLE ROLE_PERMISSIONS (
    ID NUMBER NOT NULL,
    ROLE_ID VARCHAR2(4000),
    PERMISSION_ID VARCHAR2(4000),
    CONSTRAINT PK_ROLE_PERMISSIONS PRIMARY KEY (ID)
);

-- 表: TRACKS
CREATE TABLE TRACKS (
    ID NUMBER NOT NULL,
    FLOOR_ID NUMBER,
    NAME VARCHAR2(4000),
    TRACK_TYPE VARCHAR2(4000),
    POINTS_JSON CLOB,
    COLOR VARCHAR2(4000),
    SPEED FLOAT,
    CREATED_AT VARCHAR2(4000),
    CONSTRAINT PK_TRACKS PRIMARY KEY (ID)
);

-- 表: USERS
CREATE TABLE USERS (
    ID VARCHAR2(4000) NOT NULL,
    USERNAME VARCHAR2(4000) NOT NULL,
    DISPLAY_NAME VARCHAR2(4000) NOT NULL,
    EMAIL VARCHAR2(4000),
    DEPARTMENT VARCHAR2(4000),
    ROLE VARCHAR2(4000),
    WINDOWS_SID VARCHAR2(4000),
    LAST_LOGIN_AT VARCHAR2(4000),
    CREATED_AT VARCHAR2(4000),
    UPDATED_AT VARCHAR2(4000),
    CONSTRAINT PK_USERS PRIMARY KEY (ID)
);

-- 表: VEHICLES
CREATE TABLE VEHICLES (
    ID VARCHAR2(4000) NOT NULL,
    NAME VARCHAR2(4000),
    VEHICLE_TYPE VARCHAR2(4000),
    FLOOR_ID NUMBER,
    TRACK_ID NUMBER,
    STATE VARCHAR2(4000),
    PROGRESS FLOAT,
    LOT_ID VARCHAR2(4000),
    TARGET_MACHINE_ID VARCHAR2(4000),
    SPEED FLOAT,
    UPDATED_AT VARCHAR2(4000),
    CONSTRAINT PK_VEHICLES PRIMARY KEY (ID)
);

