-- ============================================

-- CHAMBER_SNAPSHOTS 自动ID
CREATE SEQUENCE SEQ_CHAMBER_SNAPSHOTS START WITH 1 INCREMENT BY 1 NOCACHE NOCYCLE;

CREATE OR REPLACE TRIGGER TRG_CHAMBER_SNAPSHOTS_ID
BEFORE INSERT ON CHAMBER_SNAPSHOTS
FOR EACH ROW
BEGIN
    IF :NEW.ID IS NULL THEN
        SELECT SEQ_CHAMBER_SNAPSHOTS.NEXTVAL INTO :NEW.ID FROM DUAL;
    END IF;
END;
/

